"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[84856],{14644:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"CIWSConfig","desc":"Tuning for the train-mounted CIWS (tier 3, physical line: a Phalanx-style\\nsix-barrel rotary gun, crewed). Same fields as `AutoCannonConfig`: it runs on\\nthe shared shell-turret code (`ShellTurretServer`, `TrainTurret/ShellWeapon`,\\n`BurstCannonMath`) in magazine mode. One barrel key (`C`, the cluster centre),\\n`BurstSize = 1` full-auto, `BlastRadius = 0` (every round is a direct hit on one\\nenemy or rock, no splash). `SpinRate` turns on the client\'s cosmetic barrel\\nspin. All sound keys resolve through SoundManager/SoundConfig. Angles in\\ndegrees unless the name says otherwise.","source":{"line":14,"path":"src/ReplicatedStorage/SharedModules/Configs/CIWSConfig.luau"}}')}}]);